function showDate(){
    //Start Your code here
    var input = document.getElementById('in1').value;
    var timestamp = parseInt(input);
    var date = new Date(timestamp);
    var weekday = date.toLocaleDateString('en-US', {weekday:'short'});
    var month = date.toLocaleDateString('en-US', {month:'short'});
    var day = date.getDate();
    var year = date.getFullYear();
    var time = date.toLocaleTimeString('en-US', {hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false, timeZone:'Asia/Kolkata'});
    var dateStr = weekday + ' ' + month + ' ' + day + ' ' + year + ' ' + time + ' GMT+0530 (India Standard Time)';
    document.getElementById('result').textContent = dateStr;

}
